import{_ as l,o as i,c as t,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"2017-MAY-25 -- Ceph Tech Talk: Ceph on ARM","description":"","frontmatter":{"title":"2017-MAY-25 -- Ceph Tech Talk: Ceph on ARM","date":"2017-05-26T00:00:00.000Z","updated":"2017-05-26T00:00:00.000Z","tags":["Ceph","ARM","分布式存储","开源","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-MAY-25_--_Ceph_Tech_Talk_-_Ceph_on_ARM.md","filePath":"posts/2017/2017-MAY-25_--_Ceph_Tech_Talk_-_Ceph_on_ARM.md","lastUpdated":1780459816000}'),a={name:"posts/2017/2017-MAY-25_--_Ceph_Tech_Talk_-_Ceph_on_ARM.md"};function p(o,e,s,_,r,h){return i(),t("div",null,[...e[0]||(e[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph on ARM 工作进展及未来计划</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>：</p><ul><li>Sage Weil（Red Hat）</li><li>Steve Capper（dom）</li><li>Pankaj Brijwasi（Cavium）</li><li>Vikram（Cavium）</li><li>Davey (SUSE)</li><li>Danny (Deutsche Telekom)</li><li>Jeff Chu（ARM）</li></ul><p><strong>会议内容</strong>：</p><p><strong>1. 上游构建和基础设施现状</strong></p><ul><li>Sage 介绍了 Ceph on ARM 的历史和现状，包括 ARM 32 位和 ARM 64 位支持。</li><li>目前，Ceph on ARM 的上游构建和测试主要依赖于社区贡献的硬件和 Jenkins 服务器。</li><li>由于缺乏足够的硬件和 Jenkins 服务器资源，目前还没有进行大规模的 ARM 构建和测试。</li></ul><p><strong>2. 社区工作进展</strong></p><ul><li>Steve Capper 介绍了 dom 公司在 Ceph on ARM 领域的工作，包括 OpenStack Swift 与 Radars 网关集成、内核参数和设置参数优化等。</li><li>Pankaj Brijwasi 介绍了 Cavium 公司在 Ceph on ARM 领域的工作，包括基于 ARM 平台的数据中心处理器、Cavium ARM 服务器等。</li><li>Davey 介绍了 SUSE 公司在 Ceph on ARM 领域的工作，包括提供 ARM 64 位平台上的 Ceph 企业存储产品。</li><li>Danny 介绍了 Deutsche Telekom 公司在 Ceph on ARM 领域的工作，包括性能测试、构建 Luminous 平台、安全性等。</li></ul><p><strong>3. 下一步行动计划</strong></p><ul><li>Sage 提出了以下行动计划： <ul><li>完善上游 Ceph on ARM 构建，使其成为每个发布版本的一部分。</li><li>在 Jenkins 上设置 CI/CD 流程，以测试每个 pull request 和 master 分支。</li><li>提供可用的 ARM 二进制文件。</li><li>探索使用 OpenStack 作为构建和测试平台的可能性。</li></ul></li><li>Jeff Chu 提出了以下行动计划： <ul><li>建立一个协调机制，以了解社区中正在进行的工作。</li><li>鼓励社区成员参与 ARM 构建和测试工作。</li><li>探索在 ARM 平台上实现架构特定优化的机会。</li></ul></li></ul><p><strong>4. 其他讨论</strong></p><ul><li>会议讨论了以下问题： <ul><li>是否应该继续支持 ARM 32 位构建？</li><li>如何提高 ARM 构建和测试的效率？</li><li>如何鼓励更多社区成员参与 Ceph on ARM 的工作？</li></ul></li></ul><p><strong>5. 会议总结</strong></p><p>本次会议讨论了 Ceph on ARM 的工作进展和未来计划，并确定了下一步行动计划。社区成员对 Ceph on ARM 的兴趣和投入令人鼓舞，相信在大家的共同努力下，Ceph on ARM 将会取得更大的进步。</p>',16)])])}const u=l(a,[["render",p]]);export{C as __pageData,u as default};
